  "inhalt": "In diesem Seminar befassen wir uns mit aktuellen Forschungsthemen in der Bioinformatik, z. B. mit schnellen Alignment-Methoden oder dem Zusammenfügen einzelner Sequenzen. Wir bieten eine Reihe von Themen und zugehörigen Veröffentlichungen zur Auswahl an, und jeder Teilnehmer hält einen mündlichen Vortrag und verfasst einen Bericht über sein gewähltes Thema.",
  "ziele": "Die Studierenden können unter Anleitung selbstständig ein anspruchsvolles Thema durch systematische Forschung bearbeiten. Die Studierenden sammeln Erfahrung im Halten eines Fachvortrags und im Verfassen eines Fachberichts in Bioinformatik. Sie fassen Konzepte und Methoden von Algorithmen in der Bioinformatik zusammen, bewerten, klassifizieren, stellen sie wissenschaftlich korrekt dar und präsentieren sie. Die Studierenden erhalten zum einen einen Überblick über den Stand der Technik von Algorithmen in der Bionformatik. Andererseits wissen sie, dass es in diesem Bereich noch viele offene Forschungsfragen gibt. Durch das Studium aktueller Artikel haben die Studierenden nicht nur ihre Lese- und Lernfähigkeit, sondern auch ihre Eigenverantwortung verbessert. Die im Seminar angewandte Lernform soll den Studierenden helfen, Selbstvertrauen (Präsentation) und Kritik- und Kommunikationsfähigkeit (anschließende Diskussion) zu entwickeln.",
