  "pruefung": "Mündlicher Vortrag (ca. 30 Minuten) und schriftliche Ausarbeitung (ca. 10 Seiten), einmal Diskussionsleitung",
  "inhalt": "In diesem Seminar werden aktuelle Themen aus dem Bereich der computergestützten RNA-Bioinformatik diskutiert. Dies können unter anderem die folgenden sein: Faltung: RNA-Struktur, Thermodynamik, grundlegende Faltung; RNA-Abstrakte Formen; Vergleichende Strukturvorhersage: Strukturvergleich, Alignment-Faltung, Konsensformen; Strukturvergleich: Strukturmetriken, Baum-Alignment, Mehrfachstruktur-Alignment; RNA-Genvorhersage: Vorhersage aus Modellen, Vorhersage aus Faltung, Vorhersage aus Vergleichen; miRNAs: miRNA-Vorhersage, miRNA-Zielvorhersage; Stochastische Modelle: HMMs, SCFGs, Modelltraining; 3D-Modellierung; Cofolding; RNA-Motive und weitere Themen, ergänzt durch aktuelle Forschung.",
  "ziele": "Die Studierenden können unter Anleitung selbstständig ein anspruchsvolles Thema durch systematische Forschung bearbeiten. Die Studierenden sammeln Erfahrung im Halten eines Fachvortrags und im Verfassen eines Fachberichts in Bioinformatik. Sie können Konzepte und Methoden der bioinformatischen RNA-Biologie zusammenfassen, bewerten, einordnen, wissenschaftlich korrekt darstellen und präsentieren. Die Studierenden erhalten zum einen einen Überblick über den aktuellen Wissensstand im Bereich der bioinformatischen RNA-Biologie und damit über die Bedeutung dieses Teilgebietes der Bioinformatik. Durch das Studium aktueller Artikel haben die Studierenden nicht nur ihre Lese- und Lernkompetenz, sondern auch ihre Eigenverantwortung gestärkt. Die im Seminar angewandte Lernform soll den Studierenden helfen, Selbstvertrauen (Präsentation) und Kritik- und Kommunikationsfähigkeit (anschließende Diskussion) zu entwickeln.",
