  "pruefung": "Mündlicher Vortrag (ca. 30 Minuten) und schriftliche Ausarbeitung (ca. 10 Seiten), einmal Diskussionsleitung",
  "inhalt": "In diesem Seminar werden Ansätze des maschinellen Lernens mit Anwendungen in der Bioinformatik diskutiert. Dies können u.a. sein: überwachte Klassifikation; Deep Learning in der Bioinformatik, Support Vector Machines für die Klassifikation; Dimensionsreduktionsverfahren; probabilistische graphische Modelle; Anwendungen in den Bereichen Genomik, Transkriptomik, Evolution, Systembiologie, Text Mining und weitere Themen, die durch aktuelle Forschung ergänzt werden, werden diskutiert.",
  "ziele": "Die Studierenden können selbstständig unter Anleitung ein anspruchsvolles Thema durch systematische Recherche bearbeiten. Sie fassen Konzepte und Methoden des maschinellen Lernens, die auf bioinformatische Fragestellungen angewendet werden, zusammen, bewerten, klassifizieren, stellen sie wissenschaftlich korrekt dar und präsentieren sie. Die Studierenden erhalten zum einen einen Überblick über moderne Erkenntnisse im Bereich des maschinellen Lernens und deren Bedeutung für verschiedene Fragestellungen in der Bioinformatik. Andererseits erfahren die Studierenden, dass es in diesem Bereich noch viele offene Forschungsfragen gibt. Durch das Studium aktueller Artikel haben die Studierenden nicht nur ihre Lese- und Lernfähigkeit, sondern auch ihre Eigenverantwortung verbessert. Die im Seminar angewandte Lernform soll den Studierenden helfen, Selbstvertrauen (Präsentation) und Kritik- und Kommunikationsfähigkeit (anschließende Diskussion) zu entwickeln.",
