  "sprache": "Englisch",
  "pruefung": "Mündliche Prüfung oder Klausur bei hoher Teilnehmerzahl, rrfolgreiche Teilnahme am Seminar ist Prüfungsvoraussetzung",
  "inhalt": "Themen sind die verschiedenen Technologien der Quantitativen Biologie/Biomedizin (z.B. Omics-Technologien, Hochdurchsatz-Screening und Bildgebung), Methoden zur Prozessierung und Analyse von Hochdurchsatzdaten (Bioinformatik Workflows) und Standardisierung von Datenaustauschformaten. Des Weiteren beschäftigt sich das Modul mit Daten- und Metadatenmodellen, sowie Datenspeicherung (verschiedene Ansätze) und generellen Konzepten für das Datenmanagement (z.B. verschiedene Datenbanksysteme) und der (web-basierten) Visualisierung. Die Vorlesung bereitet dabei die technischen Grundlagen der Themen auf, und im Seminar werden aktuelle Arbeiten zur biomedizinischen Anwendung dieser Technologien von den Studenten präsentiert und diskutiert.",
  "ziele": "Die Studierenden beherrschen einfache und multivariate statistische Verfahren, sowie datengetriebene Ansätze für die Verwaltung und Analyse von biomedizinischen Hochdurchsatz und Bildgebungsdaten. Sie sind in der Lage, Forschungsinfrastrukturen zu konzipieren und Auswerteroutinen auf verschiedenen bereits existierenden Infrastrukturen methodenadäquat einzusetzen, sowie deren Einsatz in Publikationen kritisch zu hinterfragen. Die Studierenden sind darüber hinaus in der Lage, eine qualitative/quantitative Untersuchung (z.B. eine klinische Studie oder ein großangelegtes Forschungsprojekt) zu konzipieren, durchzuführen und adäquat auszuwerten (z.B. in forschungsorientierten Veranstaltungen des Studiengangs oder in der Masterarbeit). Darüber hinaus können sie die Gefahren und Chance von “Open Data” einordnen und interdisziplinär diskutieren. Die Studierenden können auch die Stärken und Schwächen qualitativer und quantitativer datengetriebener Forschung beurteilen und die methodische Qualität der Veröffentlichungen kritisch bewerten.",
  "voraussetzungen": "Es gibt keine besonderen Voraussetzungen.",
  "dozent": "Nahnsen",
  "literatur": "-",
  "zuletzt": "Sommersemester 2022",
  "geplant": "Sommersemester 2024",
