  "pruefung": "Klausur (bei kleiner Teilnehmerzahl mündliche Prüfung), Übungen können als Bonuspunkte in die Klausur einfließen.",
  "inhalt": "Internas von PostgreSQL und MonetDB, Sekundärspeicherzugriff und Datenlayout, Indexstrukturen (B+-Bäume, Hashes), multidimensionale Indexstrukturen, Sortierverfahren auf Sekundärspeichern, Anfrageauswertung, Plangenerierung und -optimierung für SQL, Transaktionen (ACID-Prinzip)",
  "ziele": "Die Rolle und Relevanz der Interna eines Datenbanksystems werden verdeutlicht und analysiert. Über das gesamte Semester hinweg stellen wir PostgreSQL und MonetDB gegenüber, sodass die Teilnehmer die Eignung disk- und hauptspeicher-basierter Datenbanktechnologie für konkrete Applikationen einschätzen können. Die Studierenden wissen diese neuen Kenntnisse mit den Konzepten der Vorlesung “DB1” zu verknüpfen. Die Studierenden verstehen, welche grundlegenden Parameter und Algorithmen einen effizienten Datenbankbetrieb ermöglichen und können diese für konkrete Anwendungsfälle optimieren. Dabei wird das Thema in einer Tiefe behandelt, die den Studierenden Lese- und Lernkompetenz vermittelt sowie Disziplin und Präzision trainiert.",
  "voraussetzungen": "Es gibt keine besonderen Voraussetzungen.",
  "dozent": "Grust",
  "literatur": "• Ramakrishnan / Gehrke: Database Management Systems• Heuer / Saake: Datenbanken: Implementierungstechniken• Relationale Datenbanksysteme (Software und Manuals): PostgreSQL,MonetDB• Klassische und aktuelle Forschungsartikel zum Thema",
