  "sprache": "Deutsch und Englisch",
  "pruefung": "Klausur",
  "inhalt": "- Einführung in Interna des Datenbanksystems DuckDB- Komprimierte Speicherformate für Tabellendaten- Lesen und Analyse komplexer Anfragepläne- Dekorrelation verschachtelter Anfragen- Vektorisierung in der Anfrageauswertung- Pipelining und Multi-Threading- Indexierung von Tabellen (Radix-Bäume)- Implementation von Anfrageoperatoren (Join, Sort)- Persistenz- Transaktionen",
  "ziele": "Diese Vorlesung studiert ausgewählte Internas von DuckDB, einem modernen Datenbanksystem, das tabellarische Daten (Relationen) sehr effizient verarbeiten kann. Die Studierenden verstehen, wie DuckDB große Datenmengen auf Sekundärspeichern (etwa SSDs) oder im RAM komprimiert epräsentiert. Die Vorlesung diskutiert Pläne für komplexe SQL-Anfragen, deren Vereinfachung und Optimierung. Zur parallelen Auswertung dieser Anfragen baut DuckDB Pipelines von Operatoren auf, durch die jeweils ganze Vektoren von Daten geschleust werden. Die Vorlesung diskutiert sowohl diese Pipelines als auch die Realisierung von Operatoren wie Join, Sortierung oder den gezielten Zugriff auf Daten mittelsRadix-Bäumen. DuckDB bewahrt im Mehrbenutzerbetrieb und auch bei Systemausfall die Integrität von Daten—die Studierenden erlernen die grundlegenden Konzepte, mittels derer das System diese Zusicherung geben kann.",
  "voraussetzungen": "Es gibt keine besonderen Voraussetzungen.",
  "dozent": "Grust",
  "literatur": "Teilnahmevoraussetzungen (optimal, aber optional):- Vorlesung \"Tabular Database Systems\" (INF 3132)- Grundlegende Kenntnisse in C oder C++- Grundlegende Kenntnisse in Python --- Prerequisites (ideal, but optional):- Lecture \"Tabular Database Systems\" (INF 3132)- Basic knowledge of C or C++- Basic knowledge of Python",
  "zuletzt": "nicht bekannt",
  "geplant": "Wintersemester 2025",
