  "inhalt": "Semantik und interne Repräsentation von SQL (z.B. Comprehensions), Compilation von SQL, Datenbanksprachen für nicht-relationale Daten, neue Paradigmen für datenintensives Programmieren, Interaktion von Datenbanken und Programmierumgebungen, Compilation von Programmiersprachenkonstruktuen zur Ausführung auf Datenbanksystemen",
  "ziele": "Die Studierenden kennen Compilationstechniken für die behandelten Datenbanksprachen. Bezüge zum klassischen Compilerbau und die Notwendigkeit neuer Übersetzungsverfahren werden erkannt. Die Studierenden kennen den zentralen Begriff des Impedance Mismatch, der das gesamte Themenfeld bestimmt. Die resultierende Problematik wird analysiert und alternative Lösungsansätze können bzgl. Verwendbarkeit und Effizienz eingeschätzt werden. Bezüge zu funktionalen Programmiersprachen (Semantik und Übersetzungsverfahren) können erkannt und ausgenutzt werden. Dabei wird das Thema in einer Tiefe behandelt, die den Studierenden Lese- und Lernkompetenz vermittelt sowie Disziplin und Präzision trainiert.",
