  "ziele": "Die Studierenden kennen weiterführende statistische Methoden, können diese anwenden und in Software implementieren. Sie können die Unterschiede zwischen frequentistischer und Bayes-Statistik einordnen. Die Studierenden sind in der Lage, Versuche selbst planen und auswerten zu können und dabei typische Fehler zu vermeiden. Sie können in der Literatur eingesetzte statistische Verfahren und dargestellte Ergebnisse kritisch hinterfragen.",
