  "pruefung": "Mündliche Prüfung (bei großer Teilnehmerzahl Klausur), durch erfolgreiche Übungen kann ein Notenbonus erarbeitet werden.",
  "inhalt": "Es werden vertiefende Lehrinhalte der Computergrafik mit dem Schwerpunkt Bildsynthese vermittelt und geübt. Das Modul behandelt grundlegende und fortgeschrittene Theorie und Algorithmen der Monte Carlo und Quasi-Monte Carlo-Simulation, behandelt globale Beleuchtungsansätze wie Path Tracing, Bidirectional Path Tracing, Metropolis Sampling, Photon Mapping, sowie Methoden zum Echtzeitrendering.",
  "ziele": "Die Studierenden erwerben vertiefende Kenntnisse in den Bereichen Monte Carlo-Approximation und globale Beleuchtungssimulation. Die Studierenden werden in die Lage versetzt, die behandelten Techniken zu analysieren und zu implementieren sowie eigenständig Problemstellungen zu bewerten, zu lösen und in eigenen Projekten anwenden zu können.",
