  "turnus": "S",
  "sprache": "Englisch",
  "pruefung": "Klausur (mündliche Prüfung bei geringer Teilnehmeranzahl)",
  "inhalt": "Es werden kognitive Modelle für Lernen, Handeln und Wahrnehmung vorgestellt und erörtert, darunter deskriptive, qualitative, quantitative und neuronale Modelle. Darüber hinaus werden die Optimierung von Parametern sowie Techniken zum Vergleich von Modellen und zur Interpretation und Bewertung von Modellparametern vorgestellt. Alle Techniken werden im Zusammenhang mit konkreten Modellen kognitiver Prozesse gezeigt. Darüber hinaus werden die notwendigen statistischen Methoden praxisnah und anwendungsorientiert vorgestellt.",
  "ziele": "Die Studierenden kennen die wichtigsten Prinzipien und Techniken der kognitiven Modellierung. Sie wissen, wie man kognitive Prozesse, Mechanismen und Lernen auf verschiedenen Komplexitätsebenen modelliert. Sie können verschiedene kognitive Modelle und Modellierungsansätze zielgerichtet anwenden. Darüber hinaus können sie verschiedene Modellierungsansätze und Modellierungsergebnisse bewerten, vergleichen und gegenüberstellen. Sie sind in der Lage zu beurteilen, ob ein Modell falsifizierbar ist und wissen, wie man kognitive Modelle validiert und interpretiert. Schließlich können sie statistische Methoden anwenden, um verschiedene kognitive Modelle quantitativ zu vergleichen.",
  "voraussetzungen": "Es gibt keine besonderen Voraussetzungen.",
  "dozent": "Butz, Wichmann",
  "literatur": "Book: S. Lewandowsky & S. Farrell (2011). Computational Modeling in Cognition.Additional papers and book chapters will be supplied. Introductory course knowledge about machine learning, artificial neural networks, robotics, cognitive architectures, or artificial intelligence is required.",
