  "pruefung": "Schriftliche oder mündliche Prüfung. Die Teilnahme an Übungen ist Voraussetzung für die Prüfungsteilnahme.",
  "inhalt": "Dieser Kurs ist eine Einführung in die interaktive Theorem-Programmierung und fortgeschrittene funktionale Programmierung, hauptsächlich unter Verwendung des Coq-Beweisassistenten. Dieser Kurs richtet sich an Studenten, die interessiert sind an:1. Die grundlegenden Theorien der Mathematik, vor allem Typentheorie und Logik2. Praktisches interaktives Beweisen von Theoremen mit einem modernen Beweisassistenten3. Fortgeschrittene funktionale Programmiersprachen und ihre Beziehung zur konstruktiven Mathematik über den \"Curry-Howard-Isomorphismus\"4. Programmverifikation und \"zertifizierte Programmierung\"5. Semantik von Programmiersprachen",
  "ziele": "Die Studierenden sind in der Lage, Programme zu schreiben und Theoreme mit dem Coq-Beweisassistenten zu beweisen. Die Studierenden verstehen die theoretischen Grundlagen von interaktiven Theorembeweisern und erhalten einen grundlegenden Einblick in die Semantik und die formalen Eigenschaften von Programmiersprachen.",
