  "inhalt": "Dieses Praktikum ist eine Einführung in die mobile Softwareentwicklung am Beispiel von Android. Im Grundlagenteil behandeln wir Konzepte wie App-Lifecycles, Navigation, Layouts, Datenhandling, System Services und Push Notifications. Im praktischen Teil planen und implementieren die TeilnehmerInnen in Gruppenarbeit eine eigene App.",
