  "sprache": "Deutsch",
  "pruefung": "Ausarbeitung und Präsentation der Praktikumsaufgaben",
  "inhalt": "Dieses Modul bietet eine Einführung in die praktische Arbeit mit Mikrocontrollern. Hierfür wird die auf einem 32-bit ARM Cortex-M0+ Prozessor basierende FRDM-KL25Z Entwicklungsplattform verwendet. Nach einer kurzen Einführung in die verwendete Plattform, werden in Zweierteams praktische Aufgaben gelöst. Die Praktikumsaufgaben umfassen die folgenden Themenbereiche: Einführung in die Programmierung von Mikrocontrollern, Ausführungszeit von Anwendungen, Leistungsanalyse und -optimierung sowie Speicheranforderungen.",
  "ziele": "Die Studierenden können systematisch Software für Eingebettete Systeme unter Berücksichtigung von elektrischen Leistungsaufnahme und des Energieverbrauchs entwickeln. Sie kennen den gesamten Entwicklungsablauf von der Spezifikation, über die Entwicklung bis hin zu Debugging und Dokumentation. Ferner sind die Studierenden in der Lage, moderne Techniken des Softwaregestützten dynamischen Power-Managements bis hin zur Programmierung von Ultra-Low-Power-Anwendungen anzuwenden. Auf Teamarbeit, Kommunikation innerhalb der Gruppen und zwischen den einzelnen Gruppen, systematisches Problemlösen und Einhalten von Terminen wird Wert gelegt. Dies fördert Selbstbewusstsein, Selbstvermarktungsfähigkeit und Konfliktfähigkeit der Studierenden.",
