  "pruefung": "Ausarbeitung und Präsentation der Praktikumsaufgaben",
  "inhalt": "Das Praktikum behandelt aktuelle Forschungsfragen der Rechnerarchitektur anhand praktischer Aufgabestellungen. Hierzu gehören Praktikumsaufgaben zu folgenden Themen: Simulative Bewertung von Rechnerarchitekturen, Mikroarchitektur und Befehlssätze, Sprungvorhersagen und spekulative Ausführung, Caches und Cachekohärenz, Speicherorganisation und Verbindungsnetzwerke sowie Unterstützung von Betriebssystemen durch die Rechnerarchitektur. Zusätzlich bildet ein eigenständig erarbeitetes Forschungsprojekt den Abschluss des Praktikums.",
  "ziele": "Dieses Praktikum versetzt die Studierenden in die Lage, aktueller Forschungsfragen aus dem Bereich der Rechnerarchitektur zu bewerten und neue Fragestellungen selbständig zu bearbeiten. Durch den praktischen Umgang mit Parallelarchitekturen und parallelisierten Anwendungen erlangen die Studierenden ein weitergehendes Verständnis über die Komplexität paralleler Vorgänge und die daraus resultierenden Schwierigkeiten. Die selbständige Bearbeitung der Aufgaben befähigt die Studierenden, mit für den Alltag in Wissenschaft und Wirtschaft relevanten Methoden und Werkzeugen umzugehen. Ferner erwerben sie die Kompetenz Parallelrechner effizient zu programmieren und die erlernten Fähigkeiten im Rahmen eines Forschungsprojekts vertieft anzuwenden. Die im Rahmen dieses Moduls gestellten Aufgaben werden in kleinen Gruppen bearbeitet. Dies trainiert neben Team-, Kommunikations- und Konfliktfähigkeiten auch das Verantwortungsbewusstsein der Studierenden.",
  "voraussetzungen": "INFO-4317 Parallele Rechnerarchitekturen",
  "dozent": "Bringmann",
  "literatur": "• J. L. Hennessy, D. A. Patterson: Computer Architecture: A Quantitive Approach, Morgan Kaufmann Publishers Inc, Elsevier, 6. Auflage, 2018.",
