  "inhalt": "Einführende Vorlesungseinheiten zu jedem Versuch, praktische Übungen zuhause zum Kennenlernen der Experimentierumgebung (Linux-Kommandozeile, Basisbefehle für Netzadministration, Mitschneiden von Verkehr) sowie benotete Präsenzübungen im Experimentallabor zu fortgeschrittenen Themen. Wechselnde Themen zu aktuellen Kommunikationstechnologien.",
  "ziele": "Die Studierenden vertiefen ihre praktischen Kenntnisse zu Kommuniktionsnetzen wesentlich, insbesondere zu den vermittelten Themen. Sie können sehr anspruchsvolle Konfigurationen von Rechnernetzen selbständig durchführen und Eigenschaften von fortgeschrittenen Protokollen experimentell evaluieren. Sie können sich selbständig neues Wissen und Können aneignen und ihre Fähigkeiten zur Problemlösung auch in neuen und unvertrauten Kontexten anwenden. Sie lernen ihr Wissen in klarer und eindeutiger Weise zu kommunizieren und auf wissenschaftlichem Niveau auszutauschen.",
