  "sprache": "Deutsch und Englisch",
  "pruefung": "Klausur, Übungsleistungen können als Bonuspunkte in die Klausur einfließen",
  "inhalt": "Statistische Grundlagen (Teil 1), Einführung in die Simulationstechnik, Verteilungsfunktionen (Teil 1), Aufbereitung von Stichproben, statistische Grundlagen (Teil 2), statistische Auswertung von Simulationen, stochastische Prozesse; die Vorlesungsinhalte werden im Rahmen der Übung in die Praxis umgesetzt, insbesondere wird in mehreren aufeinanderfolgenden Übungen ein einfacher Simulator gebaut. Schwerpunkt sind die Modellierung von Problemen aus unterschiedlichen Kontexten durch geeignete Verteilungsfunktionen sowie durch Markovketten sowie die dazugehörigen, mathematischen Grundlagen.",
  "ziele": "Die Studierenden können technische Systeme in ihrer Konzeptionsphase mit anspruchsvollen Methoden modellieren und untersuchen und somit Forschung und Entwicklung effizient mitgestalten. Sie haben tiefgehende, praktische Kenntnisse zu zeitdiskreter Simulation und können Experimente systematisch aufbauen und auswerten. Sie können zeitdiskrete und zeitkontinuierliche Markovketten für die Modellierung und Untersuchung von technischen Systemen einsetzen und deren Leistungsfähigkeit mit Hilfe von Warteschlangentheorie vorhersagen. Sie sind in der Lage die erworbenen Kenntnisse in neuen Kontexten zu übertragen und anzuwenden.",
