  "inhalt": "Die Vorlesung gibt einen Überblick über relevante Technologien im Bereich NetworksSoftwarization. Dazu gehören Software-Defined Networking mittels Open-sFlow, Data Plane Programming mittels P4 sowie Virtualisierungstechniken und Network Function Virtualization. Zusätzlich werden aktuelle Forschungsthemen besprochen. Die Veranstaltung wird durch praktische Übungsprojekte begleitet, in denen die Studierenden die erlernten Technologien anwenden und anspruchsvolle Programmieraufgaben lösen.",
  "ziele": "Die Studierenden haben Kenntnisse und Fertigkeiten auf dem neusten Stand des Wissens hinsichtlich Network Softwarization und Einblick in Forschungsthemen erworben, was sie zu Forschungsarbeiten im Bereich Kommunikationsnetze in besonderer Weise befähigt. Sie haben ein tiefgehende Verständnis davon wie mit Network Softwarization neue Technologien schneller entwickelt und Netze effizienter betrieben werden können. Sie können sich selbständig neues Wissen und Können aneignen und weitgehend selbstgesteuert anwendungsorientierte Projekte durchführen. Sie sind in der Lage sich mit Fachvertretern und mit Laien über Informationen, Ideen, Probleme und Lösungen auf wissenschaftlichem Niveau auszutauschen.",
