  "inhalt": "Dieses Seminar behandelt aktuelle und wechselnde Themen aus Forschung und Anwendung auf dem Gebiet der Kommunikationsnetze.",
  "ziele": "Die Studierenden sind in der Lage, aktuelle Forschungsarbeiten auf dem Gebiet der Kommunikationsnetze zu lesen, zu reflektieren und inhaltlich zu untersuchen. Sie können die Beiträge einer Arbeit kritisch beurteilen. Sie können aktuelle Forschungsergebnisse vor anderen Studierenden und Wissenschaftlern präsentieren und Forschungsdiskussionen leiten. Sie können die Ergebnisse von Forschungsarbeiten in Form einer mündlichen Präsentation und eines schriftlichen Berichts zusammenfassen und bewerten.",
