  "inhalt": "Die Vorlesung behandelt folgende Themen. Authentisierung und Autorisierung: Theorie, Hardware-Konzepte und UNIX-Konzepte, Kryptographie: Verschlüsselung, MACs, Signaturen und Schlüsselverwaltung, der PKCS #11 Standard und Hardware Security Modules (HSMs), Sicherheit in der Cloud, Confidential Computing, Quanten-Computing",
  "ziele": "Die Studierenden verfügen über fortgeschrittene Kenntnisse in der Computersicherheit mit Hinsicht auf Hardware und Software. Sie verfügen über praxisrelevantes Spezialwissen (Grundprinzipien, nach denen ein Computer-System gesichert werden kann, Sicherheitsstandards, kryptographisches API) und können dieses auch zur Problemlösung in neuen und unvertrauten Kontexten anwenden. Sie sind in der Lage sich selbständig neues Wissen und Können anzueignen und sich mit Fachvertretern über Informationen, Ideen, Probleme und Lösungen auf wissenschaftlichem Niveau auszutauschen.",
  "voraussetzungen": "Es gibt keine besonderen Voraussetzungen.",
  "dozent": "Bündgen, Menth",
