  "ziele": "Die Studierenden beherrschen theoretische Methoden des blickbasierte Interaktion und können diese problemorientiert anwenden. Sie sind in der Lage, im Studium erworbene Fachkenntnisse und Forschungsmethoden in einem Projekt umzusetzen und auf die industrielle Praxis anzuwenden. Die Studierenden beherrschen zudem maschinelle Lernverfahren zur Analyse und Interpretation von Eye-Tracking Daten im Bereich der Mensch-Maschine-Interaktion und sind in der Lage, diese selbständig auf Problemfelder der Informatik zu übertragen und situationsangemessen anzuwenden.",
