  "inhalt": "Themen sind u.a. Matching, MinCostFlow, Lineares Programmieren, Approximationsschemata, Netzwerkanalyse, Algorithmische Geometrie, Komplexitätsfragen wie z.B. Untere Schranken.",
  "ziele": "Die Studierenden vertiefen ihre Kenntnisse über algorithmische Techniken in verschiedenen Problemfeldern. Dazu gehören die Anwendung von komplexen Graphalgorithmen, die Beherrschung von Strategien zur Netzwerkanlayse sowie die Fähigkeit, Näherungsmethoden anzuwenden und selbst zu entwickeln. Im Bereich Komplexitätsfragen können die Studierenden Probleme nach ihrem Schwierigkeitsgrad beurteilen und diese Beurteilungen mittels der erlernten Techniken auch beweisen.",
