  "pruefung": "wird noch ergänzt",
  "inhalt": "Kryptographie ist heute ein wesentlicher Bestandteil der Sicherheit aller modernen Kommunikationsmittel, der sicheren Datenspeicherung und der vertraulichen Datenverarbeitung. Diese Vorlesung bietet eine Einführung in alle grundlegenden Prinzipien, Methoden und Begrifflichkeiten im Bereich der Kryptographie sowie einen Überblick über einige der wichtigsten Anwendungen. Themen sind: • klassische kryptographische Systeme,• Pseudo-Zufallsfunktionen (PRF)/Permutationen (PRP),• Blockchiffren, DES, AES, • symmetrische Verschlüsselung,• Nachrichten-Authentifizierungs-Codes (MACs),• authentifizierte Verschlüsselung,• Hash-Funktionen,• Gruppentheorie,• Diffie-Hellman-Schlüsselaustausch,• asymmetrische Verschlüsselung,• digitale Signaturen,• sichere Mehrparteienberechnungen",
  "ziele": "wird noch ergänzt",
  "voraussetzungen": "Es gibt keine besonderen Voraussetzungen.",
  "dozent": "Akgün",
