  "ziele": "Die Studierenden verstehen die physikalischen Prinzipien der analogen und besonders der digitalen Fotografie und können die gängigen Techniken umsetzen. Die Bildbearbeitung allgemein und speziell für die Zielplattform Web ist ihnen aktiv vertraut, ebenso die algorithmische Auflösung des Bayer-Mosaics. Grundsätzliche rechtliche Fragen (Urheberrecht, Bildnisrecht) können von ihnen beantwortet werden.",
