  "sprache": "Englisch",
  "pruefung": "Klausur oder Mündliche Prüfung",
  "inhalt": "Diese Vorlesung umfasst verschiedene Bereiche der Medizinischen Informatik. Der Schwerpunkt liegt auf Datenintegration, medizinischer Datenschutz, künstliche Intelligenz und Data Mining für Gesundheitsdaten und Systeme zur Unterstützung von Behandlungsentscheidungen. Spezifische Themen sind:- Grundlagen des statistischen maschinellen Lernens- Stand der Technik bei Entscheidungsunterstützungssystemen und darüber hinaus- differentieller Datenschutz- k-Anonymität- Datensatzverknüpfung unter Wahrung der Privatsphäre- Ansätze des föderierten Lernens und GO-FAIR- Genomischer Datenschutz- FHIR- openEHR- Data Warehouses und No-SQL-Datenbanken- map reduce",
  "ziele": "Die Studierenden sind in der Lage, die wichtigsten Begriffe, Methoden und Theorien der klinischen Entscheidungsunterstützungssysteme, des medizinischen Datenschutzes sowie der Datenintegration und -analyse zu erklären. Sie sind in der Lage zu entscheiden, welche Art von Methoden für welche Art von Datensätzen geeignet sind. Die Studierenden können sich kritisch mit den Unzulänglichkeiten von State-of-the-Art-Methoden auseinandersetzen und eventuell Ideen zur Erweiterung oder Verbesserung der Methoden entwickeln.",
  "voraussetzungen": "MDZINFM1410 Grundlagen der Medizininformatik",
  "dozent": "Pfeifer",
  "literatur": "Eta S. Berner: Clinical Decision Support Systems - Theory and Practice, A.Gkoulalas-Divanis and G. Loukides: Medical Data Privacy Handbook, P. Lake and P. Crowther: Concise guide to databases / recommended: Grundlagen der Medizininformatik",
