  "inhalt": "Belegt werden folgenden Veranstaltungen:- Bioimaging (3 ECTS): Image Correction, Functional MRI, Hyperpolarized MRI, Principles of Combined PET/MR Imaging, Basics of Image Reconstruction, Imaging and Metabolomics (MRI, NMR), Advanced Tracer development and production, MR Angiography, Research in Radiochemistry, Pharmacological Modelling- Nanoanalytics/Interfaces I (3 ECTS): Introduction to statistical physics, soft matter and polymer physics, mechanics of cells and tissues, physics of the cytoskeleton, cellular forces, motor proteins, methods in nanobiophysics, high resolution microscopy techniques, micro- and nanofluidics, lab-on-a-chip technology.- Implantology (3 ECTS): Vital implants: Tissue engineering, cell biology, biomaterials, reactor technology. Avital implants: Interface between tissue and man-made materials, signal acquisition and processing, biostability, biocompatibility, operational procedures, design and use in clinical trials.Das Modulhandbuch M.Sc. Biomedical Technologies für das jeweils aktuelle Semester ist unter \\url{http://www.medizin.uni-tuebingen.de/Studierende/Medizintechnik/Masterstudiengang+_Biomedical+Technologies_-port-10011-p-66480.html} zu finden.",
  "ziele": "Die genauen Qualifikationsziele sind dem Modulhandbuch M.Sc. Biomedical Technologies zu entnehmen. Diese ist für das jeweilig aktuelle Semester unter \\url{http://www.medizin.uni-tuebingen.de/Studierende/Medizintechnik/Masterstudiengang+_Biomedical+Technologies_-port-10011-p-66480.html} zu finden.",
