  "pruefung": "Mündliche Präsentation und schriftliche Ausarbeitung",
  "inhalt": "Das Seminar behandelt aktuelle Forschungsthemen und -trends im Bereich Datenschutz. Die Themenbereiche umfassen u.a. (aber nicht nur) Datenschutz im Bereich der Sozialen Netzwerke, des Maschinellen Lernens und biomedizinischer Daten.",
  "ziele": "Die Studierenden lernen aktuelle Forschungsliteratur im Bereich Datenschutz kennen und lernen, diese zusammenzufassen und zu präsentieren. Sie sind in der Lage, den Beitrag eines Forschungsartijels kritisch zu bewerten. Sie können aktuelle Forschungsergebnisse anderen Studierenden und Forschenden präsentieren und Forschungsdiskussionen dazu leiten. Sie können die Ergebnisse von Forschungsartikeln mündlich sowie schriftlich zusammenfassen und bewerten.",
