  "sprache": "Englisch",
  "pruefung": "Mündliche Präsentation über einen wissenschaftlichen Artikel (30 min) und schriftlicher Bericht (8 Seiten)",
  "inhalt": "Die großen Fortschritte, die große Sprachmodelle (LLMs) im Bereich der natürlichen Sprachverarbeitung (NLP) gemacht haben, haben das Interesse an vielen biomedizinischen Aufgaben, darunter klinische Studien und Patientenabgleich, neu geweckt. Das Seminar behandelt aktuelle Forschungsthemen im Bereich der generativen KI und deren Anwendung im klinischen Studienabgleich sowie ein optionales Projekt zur Erstellung eines eigenen Kohortenentdeckungsmodells.",
  "ziele": "Die Studierenden sind in der Lage, den Beitrag einer Forschungsarbeit zum Forschungsfeld kritisch zu untersuchen. Sie können Forschungsergebnisse unter den Gesichtspunkten Transparenz, Erklärbarkeit, Verallgemeinerbarkeit und Fairness lesen, bewerten und diskutieren. Im Rahmen des Seminars werden die Studierenden die Ergebnisse von Forschungsarbeiten in Form einer mündlichen Präsentation und eines schriftlichen Berichts zusammenfassen und bewerten.",
