  "turnus": "U",
  "sprache": "Englisch",
  "pruefung": "Klausur (mündliche Prüfung bei geringer Teilnehmeranzahl)",
  "inhalt": "Teil 1: Grundlegende Ergebnisse der statistischen Lerntheorie:- Statistischer Aufbau, Schätz- und Approximationsfehler, Stetigkeit- Negative Ergebnisse: No free lunch theorem, langsame Konvergenzraten- Stetigkeit von k-Nächster-Nachbar-Algorithmen und Partitionierungsalgorithmen- Ungleichungen der Konzentration- Einfache Verallgemeinerungsschranken, z. B. mit Zersetzungskoeffizienten und VC-Dimension- Fortgeschrittene Verallgemeinerungsschranken, z. B. mit Rademacher-Komplexitäten, algorithmischer Stabilität, Stichprobenkompression.- Regularisierung und ihre BeständigkeitTeil 2: Fortgeschrittene Ergebnisse der statistischen Lerntheorie. Dieser Teil der Vorlesung ändert sich je nach Interesse der Zuhörer und dem aktuellen Stand der Stand der Technik auf diesem Gebiet und deckt einige der neuesten Ergebnisse der Lerntheorie ab. Er kann Themen wie Online-Lernen, Theorie des unüberwachten Lernens, Theorie Deep Learning, etc.",
  "ziele": "Die Studierenden lernen die Standardinstrumente und -ansätze der statistischen Lerntheorie kennen. Sie verstehen positive und negative Ergebnisse in der Lerntheorie, insbesondere was die grundlegenden Grenzen des maschinellen Lernens sind und welche Eigenschaften wichtig sind, damit ein maschineller Lernalgorithmus funktioniert.",
