  "inhalt": "Die Vorlesung gibt eine Einführung in die Grundlagen der Wahrscheinlichkeitstheorie, Statistik, Informationstheorie, Daten(vor)verarbeitung und Indexierungstechniken, Graphendarstellungen und Linkanalyse, Klassifikation, Clustering und Themenmodelle, probabilistische Inferenz in grafischen Modellen.",
  "ziele": "(1) Die Studierenden erwerben umfangreiche Kenntnisse in Theorie und Anwendung von Methoden aus dem Bereich der Datenwissenschaft.(2) Die Studierenden erlernen verschiedene datenwissenschaftliche Techniken zum konzeptionellen Denken, zur Problemformalisierung und zur Problemlösung.(3) Die Studierenden werden an anspruchsvolle Forschungsfragen aus dem Bereich der Datenwissenschaften herangeführt.",
