  "turnus": "S",
  "sprache": "Englisch",
  "pruefung": "Vortrag und schriftlicher Projektbericht (oder Klausur, wird noch festgelegt)",
  "inhalt": "Die Vorlesung deckt das gesamte Themenspektrum des Reinforcement Learning ab, vom grundlegenden Formalismus und der Theorie bis hin zu modernen Algorithmen.Die Vorlesung wird von Übungen begleitet, die helfen, das mathematische Verständnis zu vertiefen und praktische Erfahrungen bei der Implementierung von Algorithmen zu sammeln. - Einführung in überwachtes Lernen und Optimierung- Grundlagen des Reinforcement Learning (RL) und von Markov-Entscheidungsprozessen- Dynamische Programmierung, Vorhersage und Kontrolle- Approximation von Wertfunktionen- Policy-Gradient- Deep RL, Steuerung in kontinuierlichen Zustands-Aktions-Domänen- Optimale Steuerung und modellbasiertes RL- Fortgeschrittene Themen in RL",
  "ziele": "(1) Die Studierenden können ein Problem im Formalismus des Reinforcement Learning ausdrücken und einen geeigneten Algorithmus zu dessen Lösung auswählen.(2) Die Studierenden sind in der Lage, eine Reihe von Deep Reinforcement Learning Algorithmen zu implementieren und deren Verhalten zu analysieren.(3) Die Studierenden können die Herausforderungen beim Reinforcement Learning erklären und neue Reinforcement Learning Methoden bewerten und charakterisieren.",
