  "sprache": "Englisch",
  "pruefung": "Oral/written depending on number of students",
  "inhalt": "The goal of this lecture is to learn the most recent AI 3D vision techniques for understanding and reconstructing the 3D world from videos and images. We will cover the fundamentals of multiple view geometry and quickly dive into the most recent methods covering Nerf, Gaussian Splats, 3D diffusion models and token based reconstruction methods. There will be practical assignments. In contrast to the computer vision lecture, which is of broader scope, the focus here will be on recent AI advances in the field of 3D computer vision.",
