  "ziele": "Die Studierenden besitzen Grundlagenwissen über maschinelles Lernen auf moderner statistischer Basis. Sie kennen math. statistische Herangehensweisen für die Lösung von Mustererkennungsproblemen und können diese in Übungsaufgaben anwenden. Eine weitere Voraussetzung sind fundierte mathematische Kenntnisse, insbesondere in Linearer Algebra, Statistik und Analyse.",
