  "inhalt": "In diesem Seminar werden die aktuelle VeröUentlichungen im Bereich des multimodalen Lernens behandelt wie z.B. Konzeptes des unüberwachten Lernens, Deep Learning, Transferlernen und des kontinuierlichen Lernens, um mehrere Modalitäten wie Bilder, Audio, Video zu kombinieren. Darüber hinaus können Techniken zur Datenfusion und ihre Rolle im Bereich des multimodalen Lernens behandeltwerden. Die Studierenden haben die Möglichkeit, veröUentlichten Code zu nutzen und damit zu experimentieren. Ziel ist es, ein besseres Verständnis für die Möglichkeiten und Herausforderungen des multimodalen Lernens zu entwickeln.",
  "ziele": "Die Studierenden sammeln Erfahrungen im Bereich der Erforschung multimodaler Modelle und erhalten Einblick in aktuelle Trends und Forschungsergebnisse im Bereich des multimodalen Lernens. Nach diesem Kurs sollten die Studierenden in der Lage sein, aktuelle Forschungsarbeiten zum multimodalen Lernen zu verstehen, zu reflektieren und zu kommunizieren.",
