  "turnus": "U",
  "sprache": "Englisch",
  "pruefung": "Report, Review, Presentation, Participation",
  "inhalt": "Unter der Modulnummer ML-4507 bietet die Gruppe für Autonomes Maschinelles Sehen regelmäßig Proseminare und Seminare an. Derzeit werden folgende Proseminare und Seminare angeboten: Wintersemester: Proseminar/Seminar: 3D Visionhttps://uni-tuebingen.de/de/215287 Sommersemester:Proseminar/Seminar: Autonomous Visionhttps://uni-tuebingen.de/de/222456",
  "ziele": "Die Studierenden erwerben ein tiefes Verständnis für ein wissenschaftliches Thema. Sie lernen, relevante Literatur effizient zu suchen, zu navigieren und zu lesen und ein Thema in eigenen Worten in einem schriftlichen Bericht klar zusammenzufassen. Darüber hinaus präsentieren die Studierenden ihr Thema vor einem Publikum aus Studierenden und Forschern und geben anderen ein Feedback in Form von Rezensionen und Diskussionen. Während des Seminars lernen die Studierenden, wissenschaftliche Forschung in einen Kontext zu stellen, kritisches Denken zu üben und Vorteile und Probleme einer untersuchten wissenschaftlichen Methode zu erkennen.",
