  "pruefung": "Mündliche Präsentation, schriftlicher Bericht, Laborjournal",
  "inhalt": "Das Praktikum besteht darin, in kleinen Teams selbstständig oder unter Aufsicht gestellte Aufgaben zu bearbeiten. Die Studien- und Prüfungsleistungen werden in der Regel durch aktive Mitarbeit, Präsentation der Ergebnisse und schriftliche Berichte bewertet. Im Sommersemester 2026 wird das Praktikum \"Build your own StudyOS with Modern Agentic Systems\" (Prof. Gehler) angeboten (siehe: https://alma.uni-tuebingen.de:443/alma/pages/startFlow.xhtml?_flowId=detailView-flow&unitId=67159&periodId=229&navigationPosition=studiesOffered,searchCourses)",
  "ziele": "Die Studierenden sammeln praktische Erfahrungen im Entwurf und in der Programmierung von Methoden/Software/Werkzeugen für ML. Sie sind in der Lage, Bibliotheken und Frameworks zu nutzen und erwerben Kenntnisse oder erweitern ihre Kenntnisse in verschiedenen Programmiersprachen. Durch die Zusammenarbeit in Gruppen erwerben die Studierenden Teamfähigkeit und Kooperationsfähigkeit und lernen Projektorganisation und Präsentationstechniken kennen. Die Studierenden kennen die Stärken und Schwächen sowie die Grenzen verschiedener Methoden zur Auswertung komplexer und hochdimensionaler Daten und können diese Methoden beschreiben und bewerten.",
