  "ziele": "Die Studierenden wissen, wie aktuelle Ansätze des Maschinellen Lernens in den Bereichen Segmentierung, 3D-Rekonstruktion, Szenenanalyse, Rendering, Interaktion oder Sprachverarbeitung effizient implementiert werden können. Sie können selbständig in Gruppen Programmierprojekte planen und durchführen, bei denen Neuronale Netze, Transformer oder andere ML-Ansätze zur Datenakquisition, Rekonstruktion und Repräsentation sowie zur natürlichsprachlichen Interaktion oder Erklärung eingesetzt werden.",
