  "sprache": "Englisch",
  "pruefung": "Projektpräsentation und Ausarbeitung",
  "inhalt": "Das Praktikum konzentriert sich auf die Implementierung von fortgeschrittenen Anwendungen und neusten Forschungsergebnissen im Bereich Computer Vision- und Multimodal Learning. Das Projekt umfasst eine praktische Implementierung verschiedener Techniken zur Identifizierung und Lösung von Problemen sowie zur Bewertung der Ergebnisse im Vergleich zu öffentlichen Benchmarks. Darüber hinaus vermittelt es ein Verständnis der Eigenschaften von Modellen und Benchmarks wie z.B. deren Generalisierung und Robustheit. Das Praktikum soll darüber hinaus Einblicke in die Entwicklung neuartiger Multimodal Learning-Technologien bieten.",
  "ziele": "Die Studierenden sammeln praktische Erfahrungen in der Arbeit mit und der Erforschung von aktuellen multimodalen Modellen. Nach diesem Kurs sollten die Studierenden in der Lage sein, aktuelle Forschungsarbeiten zum multimodalen Lernen zu verstehen und zu reproduzieren sowie auf der Grundlage aktueller Forschung eigene Ideen umzusetzen und zu bewerten.",
